/** Look up the segments for a (reciter, verse) pair. Returns null when
 *  the reciter has no segment bucket (e.g. Maher Al-Muaiqly) or the
 *  verse hasn't been fetched yet — caller should disable the marker. */
export function getQuranSegments(reciter: ReciterId, verseKey: string): SegmentEntry | null {
  return QURAN_SEGMENTS[reciter]?.[verseKey] ?? null;
}
